    question: 'アスファルト舗装のプライムコート・タックコートに関する記述として、最も不適当なものはどれか。',
    choices: [
      { key: 'A', text: 'プライムコートは、路盤の上に散布し、路盤とその上のアスファルト混合物層とのなじみをよくするとともに、路盤の水分逸散を防ぐ役割がある。', explanation: '適当。路盤面に浸透させ、層間の付着性向上・防水性確保を図る目的がある。' },
      { key: 'B', text: 'タックコートは、既設のアスファルト舗装面や基層面に散布し、新たに施工する層との接着性を高める役割がある。', explanation: '適当。層間はく離を防止するための重要な工程である。' },
      { key: 'C', text: 'プライムコートとタックコートは同じ役割を持つため、路盤の上に散布する場合には常にタックコート用の乳剤を用いる。', explanation: '不適当。プライムコートとタックコートは散布対象・使用する乳剤・目的が異なる。プライムコートは主に「路盤面」に散布し浸透性のある乳剤を用いるのに対し、タックコートは「アスファルト層面」に散布し接着性を重視した乳剤を用いる。両者を同一に扱う記述は不適当である。' },
      { key: 'D', text: 'プライムコート・タックコートの散布量は、散布対象面の状態や気象条件等を考慮して定める。', explanation: '適当。散布面の状態・気象条件に応じて適切な散布量を設定する。' },
    ],
    correctKey: 'C',
    explanation: 'プライムコート＝路盤面用（浸透性）、タックコート＝層間接着用。目的が異なる。\n【図解】プライムコート・タックコートの違い\n　プライムコート：路盤面に散布★・浸透性乳剤・水分逸散防止\n　タックコート：アスファルト層面に散布★・接着性重視\n　⚠両者は目的・乳剤が異なり同一に扱えない\n　→散布量は面の状態・気象条件で調整\n　×「常にタックコート用乳剤」は不適当',
    difficulty: 'advanced',
