    explanation: '高精度測位にはRTK-GNSS等、基準局からの補正情報を用いる方式が必要。\n【図解】GNSS位置情報管理の要点\n　GNSS：複数衛星の電波で位置を測位★\n　⚠高精度（数cm）にはRTK-GNSS等の補正情報が必要★（単独測位のみは不十分）\n　→機械の稼働状況・位置を遠隔把握（運行管理）★\n　○上空視界の悪化は測位精度に影響\n　×「補正情報不要」は不適当',
    difficulty: 'advanced',
