    explanation: '安全巡視の結果は記録に残し、是正措置の実施状況を管理することが望ましい。\n【図解】安全巡視・パトロールの要点\n　○不安全な状態・行動の発見・是正が目的★\n　○管理者巡視＋経営層/第三者の定期巡視★\n　⚠発見事項は記録を残し是正状況を管理（口頭注意のみは不十分）\n　→巡視結果を安全教育・KY活動にフィードバック★\n　×「記録不要」は不適当',
    difficulty: 'standard',
